});

test('addLine and removeLine: chain operations', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);

  const add1Result = addLine(result.value, { sku: 'DES-HOUR', qty: 3 });
  assert(add1Result.ok);
  assert.equal(add1Result.value.lines.length, 2);

  const add2Result = addLine(add1Result.value, { sku: 'COPY-HOUR', qty: 2 });
  assert(add2Result.ok);
  assert.equal(add2Result.value.lines.length, 3);

  const removeResult = removeLine(add2Result.value, 'DES-HOUR');
  assert(removeResult.ok);
  assert.equal(removeResult.value.lines.length, 2);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(removeResult.value.lines[1].sku, 'COPY-HOUR');
});

